def author(add):
    add(1,'빗방울 우체통','통합','생활 설명','EXP-V1-1',[
      '우리 반 문 앞에는 작은 우체통이 있어요. 우체통은 파란색이에요. 앞에는 빗방울 모양이 붙어 있어요. 친구들은 이 통을 빗방울 우체통이라고 불러요.',
      '우체통에는 고마운 마음을 쓴 쪽지를 넣어요. 받는 친구의 이름은 쪽지 바깥에 써요. 이름이 있어야 누구에게 줄지 알 수 있어요. 이름을 쓰지 않은 쪽지는 선생님이 따로 두어요.',
      '금요일에 우체통을 열어요. 도우미가 이름을 보고 쪽지를 나눠 줘요. 민우는 쪽지를 접기 전에 친구 이름을 다시 살폈어요. 자기가 쓴 마음이 다른 친구에게 가지 않게 하려는 거예요.'],
      ('우체통에 넣는 것은 무엇인가요?','고마운 마음을 쓴 쪽지',[('빌리고 싶은 책','책을 빌리는 통이라는 설명은 없어요.'),('잃어버린 물건','잃어버린 물건을 넣는 곳이라고 하지 않았어요.')],'고마운 마음을 쓴 쪽지','둘째 부분에서 우체통에 넣을 쪽지의 내용을 알려 주어요.'),
      ('쪽지 바깥에 이름을 쓰는 까닭은 무엇인가요?','받는 친구에게 쪽지를 나누어 주기 위해서예요.','이름이 있어야 누구에게 줄지 알 수 있어요.',['받는 사람 확인','이름과 전달의 관계']),
      ('classification','다음 내용을 ‘겉모습 / 쓰임 / 여는 때’로 나누세요.',['파란색','마음을 쓴 쪽지 전달','금요일'],'겉모습: 파란색 / 쓰임: 마음을 쓴 쪽지 전달 / 여는 때: 금요일','우체통은 파란색이에요.'),
      ('다른 반 친구에게 우체통을 두 문장으로 소개하세요.','어떤 모습인지와 무엇을 하는 곳인지 하나씩 고르세요.','우리 반 우체통은 파란색이에요. 고마운 마음을 쓴 쪽지를 넣는 곳이에요.',['겉모습 한 가지 포함','쪽지를 전달하는 쓰임 포함']),
      ('이름이 있어야 누구에게 줄지 알 수 있어요.','이름을 쓰라는 말 뒤에서 까닭을 찾아볼게. 받는 사람을 알 수 있어야 쪽지를 제대로 줄 수 있구나. 색깔을 설명한 문장과 쓰임을 설명한 문장을 구별해야겠어.'),
      [('도우미','다른 사람의 일을 도와주는 사람'),('바깥','접었을 때 겉으로 보이는 쪽')],
      ('모자 바구니','교실 모자 바구니는 둥글고 노란색이에요.\n바구니에는 산책할 때 쓰는 모자를 넣어요. 공은 옆 상자에 넣어요.','모자 바구니의 모습 한 가지와 쓰임을 말하세요.','노란색이거나 둥글고, 산책 모자를 넣는 데 써요.','산책할 때 쓰는 모자를',['모습 한 가지','모자 보관 쓰임']),
      ('작은 전시대','종이 안내에는 전시대가 길쭉하고 초록색이라고 쓰여 있어요. 친구들이 만든 종이배를 올려 두는 곳이에요. 가방은 걸지 않아요.','안내를 보고 전시대에 무엇을 두어야 하는지, 그 모습은 어떤지 설명하세요.','초록색이거나 길쭉한 전시대에 만든 종이배를 두어요.','종이배를 올려 두는 곳',['외형 정보','용도 정보']),
      ('파란색과 이름 쓰기 중 어느 것이 겉모습을 알려 주나요?','파란색이 겉모습을 알려 주어요.'))

    add(1,'차례로 이어가는 합주','음악','절차 안내','EXP-V1-3',[
      '우리는 작은 음악 놀이를 해요. 소리는 책상을 세게 치지 않고 손뼉으로 내요. 한 모둠에 세 명이 모여요. 먼저 연주할 때와 기다릴 때를 정해요.',
      '먼저 첫째 사람이 손뼉을 한 번 쳐요. 그 소리가 끝나면 둘째 사람이 두 번 쳐요. 마지막으로 셋째 사람이 한 번 쳐요. 앞사람이 끝나기 전에는 소리를 내지 않아요.',
      '한 차례가 끝나면 모두 손을 무릎에 놓아요. 처음 소리를 낸 친구부터 차례로 다른 자리에 앉아요. 새 자리에서도 첫째, 둘째, 셋째 차례를 지켜요. 빠르게 치는 것보다 서로의 소리를 듣는 것이 중요해요.'],
      ('둘째 사람은 언제 손뼉을 치나요?','첫째 사람의 소리가 끝난 뒤',[('첫째 사람과 동시에','앞사람이 끝나기 전에 소리를 내지 않아요.'),('모두 손을 무릎에 놓은 뒤','손을 무릎에 놓는 것은 한 차례가 끝난 뒤예요.')],'그 소리가 끝나면','둘째 사람의 시작을 앞사람의 소리가 끝나는 때와 연결했어요.'),
      ('빠르기보다 서로의 소리를 들어야 하는 까닭은 무엇일까요?','앞사람이 끝난 것을 알고 자기 차례에 소리를 내기 위해서예요.','앞사람이 끝나기 전에는 소리를 내지 않아요.',['기다리는 규칙','듣기와 차례 연결']),
      ('ordering','연주 순서대로 번호를 쓰세요.',['둘째가 두 번 친다','모두 손을 무릎에 놓는다','첫째가 한 번 친다','셋째가 한 번 친다'],'3 → 1 → 4 → 2','먼저 첫째 사람이'),
      ('놀이를 모르는 친구에게 첫째와 둘째 차례를 설명하세요.','먼저 할 일과 다음 할 일을 골라요.','먼저 첫째가 한 번 쳐요. 소리가 끝나면 둘째가 두 번 쳐요.',['두 행동을 정확히 씀','먼저와 다음 순서 연결']),
      ('그 소리가 끝나면 둘째 사람이','끝나면이라는 말이 다음 차례의 문을 열어 주네. 숫자만 보고 치지 말고 누구 다음인지도 찾아야겠어.'),[('차례','누가 먼저 하고 다음에 누가 할지 정한 순서')],
      ('종이 띠 연결','먼저 긴 종이 띠를 반으로 접어요. 접은 자리를 펴고, 그 자리에 별 스티커를 붙여요. 마지막에 이름을 써요.','별 스티커를 붙이기 바로 전에 무엇을 하나요?','접은 자리를 펴요.','접은 자리를 펴고',['직전 행동 찾기']),
      ('급식 도우미 안내','할 일 카드: ① 쟁반 놓기 → ② 숟가락 놓기 → ③ 자리에 앉기. 민서는 쟁반을 놓았어요.','민서가 다음에 할 일을 카드의 순서로 설명하세요.','숟가락을 놓아요. 쟁반 놓기 다음 차례이기 때문이에요.','② 숟가락 놓기',['다음 단계','앞뒤 순서 근거']),
      ('먼저와 마지막에 밑줄을 긋고 사이에 있는 행동을 찾아요.','첫째 한 번, 둘째 두 번, 셋째 한 번이에요.'))

    add(1,'네 자루가 된 색연필','수학','수량 이야기','COM-A5',[
      '하나가 작은 통에 색연필 세 자루를 넣었어요. 빨강 한 자루, 파랑 한 자루, 노랑 한 자루예요. 하나는 통을 흔들지 않고 책상 위에 두었어요.',
      '그때 준서가 초록 색연필 한 자루를 주었어요. 하나는 초록 색연필도 같은 통에 넣었어요. 이제 통에는 색연필 네 자루가 있어요. 처음보다 한 자루 늘었어요.',
      '하나는 네 자루를 차례로 꺼내 색을 살폈어요. 색이 다른 것과 자루 수가 늘어난 것은 다른 말이에요. 초록색을 넣어서 색도 하나 더 생겼고, 색연필 수도 한 자루 많아졌어요.'],
      ('색연필이 네 자루가 된 까닭은 무엇인가요?','세 자루에 한 자루를 더 넣어서',[('세 자루에서 한 자루를 꺼내서','꺼내면 수가 줄어요. 본문에서는 더 넣었어요.'),('처음부터 네 자루였기 때문에','처음에는 세 자루라고 했어요.')],'초록 색연필도 같은 통에 넣었어요.','초록 한 자루가 더해져 세 자루가 네 자루가 되었어요.'),
      ('빨강 색연필을 꺼내고 다시 넣으면 처음 네 자루와 비교해 수가 어떻게 되나요?','다시 넣었으니 네 자루로 같아요.','이제 통에는 색연필 네 자루',['꺼냄과 되돌려 넣음 구별','최종 수 비교']),
      ('matching','처음 수 / 더 넣은 수 / 나중 수를 짝지으세요.',['1자루','4자루','3자루'],'처음 3 / 더 넣음 1 / 나중 4','처음보다 한 자루 늘었어요.'),
      ('세 자루가 네 자루가 된 일을 두 문장으로 쓰세요.','처음 상태와 달라진 일을 나누어 생각해요.','처음에는 색연필 세 자루가 있었어요. 한 자루를 더 넣어서 네 자루가 되었어요.',['처음과 나중 수','한 자루 추가 행동']),
      ('처음보다 한 자루 늘었어요.','늘었다는 말은 처음보다 많아졌다는 뜻이야. 처음 수와 들어온 수를 따로 세고 나중 수를 확인할게.'),[('늘다','수나 양이 전보다 많아지다')],
      ('주머니의 돌','주머니에 돌 두 개가 있었어요. 돌 한 개를 꺼내 바닥에 두었어요.','주머니 안의 돌은 몇 개이며 왜 그런가요?','한 개예요. 두 개에서 한 개를 꺼냈어요.','돌 한 개를 꺼내',['남은 수','감소 행동 연결']),
      ('의자 자리','의자가 세 개 있어요. 선생님이 의자 두 개를 더 가져왔어요.','지금 의자는 모두 몇 개인지 바뀐 일을 넣어 말하세요.','세 개에 두 개를 더해서 다섯 개예요.','두 개를 더 가져왔어요.',['합한 수','추가 정보 근거']),
      ('색 이름은 가리고 세 자루와 한 자루를 손가락으로 나타내세요.','손가락 세 개에 한 개를 더 펴면 네 개예요.'))

    add(1,'놀이터 안내를 고쳐요','국어','안내문 고쳐쓰기','EXP-W4',[
      '우리 반은 새 친구에게 놀이 길을 알려 주려고 해요. 놀이터는 교실에서 나가 오른쪽에 있어요. 모래 놀이는 작은 울타리 안에서 해요. 공놀이는 울타리 밖의 빈터에서 해요.',
      '지안이는 안내문을 썼어요. “놀이터는 저기에 있어요. 거기에서 놀아요.” 새 친구는 저기가 어디인지 몰랐어요. 모래 놀이와 공놀이를 어디에서 해야 하는지도 알기 어려웠어요.',
      '지안이는 저기와 거기를 분명한 말로 바꾸기로 했어요. 길을 알려 주는 말과 놀이할 자리를 알려 주는 말을 나누어 쓰면 새 친구가 찾기 쉬울 거예요. 안내문을 읽는 사람이 모르는 것을 생각해야 해요.'],
      ('새 친구가 길을 찾기 쉬운 말은 무엇인가요?','교실에서 나가 오른쪽',[('저기 가까운 곳','저기가 어디인지 여전히 분명하지 않아요.'),('내가 아는 곳','쓴 사람만 아는 곳은 새 친구에게 도움이 되지 않아요.')],'놀이터는 교실에서 나가 오른쪽','출발하는 곳과 방향을 구체적으로 알려 주어요.'),
      ('거기에서 놀아요를 고쳐야 하는 까닭은 무엇인가요?','놀이마다 자리가 달라 어디에서 놀지 알려 줘야 해요.','모래 놀이는 작은 울타리 안',['놀이별 장소 구별','독자가 모르는 정보']),
      ('matching','놀이와 장소를 짝지으세요.',['모래 놀이','공놀이'],'모래 놀이 → 울타리 안 / 공놀이 → 울타리 밖 빈터','공놀이는 울타리 밖'),
      ('새 친구에게 보여 줄 안내문을 두세 문장으로 쓰세요.','길과 두 놀이의 자리를 차례로 적어요.','놀이터는 교실에서 나가 오른쪽에 있어요. 모래 놀이는 울타리 안에서 해요. 공놀이는 울타리 밖 빈터에서 해요.',['길을 구체적으로 설명','놀이와 장소 정확히 연결']),
      ('새 친구는 저기가 어디인지 몰랐어요.','나는 아는 길이지만 새 친구는 모르네. 저기를 출발점과 방향으로 바꾸고, 거기는 놀이 이름과 자리를 붙여 써야겠어.'),[('안내문','찾거나 할 일을 알려 주는 글')],
      ('물통 자리','물통은 창문 옆 낮은 선반에 있어요. 쪽지에는 “물통은 저쪽에 있어요”라고 쓰여 있어요.','저쪽을 구체적인 말로 고쳐 한 문장을 쓰세요.','물통은 창문 옆 낮은 선반에 있어요.','창문 옆 낮은 선반',['구체적인 위치']),
      ('준비물 알림','내일 접기 시간에는 색종이 두 장이 필요해요. 알림에는 “그것을 가져오세요”라고 적혀 있어요.','그것을 바꾸고 수까지 넣어 알림을 고치세요.','색종이 두 장을 가져오세요.','색종이 두 장',['대상과 수 명시']),
      ('저기라는 말 대신 어디에서 출발해 어느 쪽으로 가는지 말하세요.','교실에서 나가 오른쪽으로 가요.'))

    add(2,'해가림 판 실험 기록','과학','가상 관찰 기록','EXP-V1-2',[
      '과학 놀이 시간에 종이로 해가림 판을 만들었어요. 이번 이야기는 관찰 방법을 연습하려고 만든 가상 기록이에요. 같은 전등 앞에 같은 크기의 흰 종이 두 장을 놓았어요. 전등과 종이 사이의 거리도 같게 했어요.',
      '가 종이 앞에는 두꺼운 판을 세웠고, 나 종이 앞에는 판을 세우지 않았어요. 두 종이의 밝기를 같은 때 살폈어요. 기록에는 가 종이가 나 종이보다 어두워 보였다고 적혀 있어요. 친구들은 무엇을 다르게 했는지 먼저 찾았어요.',
      '서연이는 “가 종이는 크기가 작아서 어두웠어”라고 말했어요. 하지만 두 종이의 크기는 같았어요. 이번에 다르게 한 것은 앞에 판을 세웠는지였어요. 다른 날의 모든 판도 같은 결과가 나올지는 이 기록만으로 알 수 없어요.'],
      ('이번 관찰에서 다르게 한 것은 무엇인가요?','종이 앞에 판을 세웠는지',[('종이의 크기','본문에서 두 장의 크기는 같게 했다고 했어요.'),('전등과 종이 사이 거리','거리도 같게 했다고 했어요.')],'가 종이 앞에는 두꺼운 판','판이 있는 경우와 없는 경우를 비교했어요.'),
      ('서연이의 말이 기록과 맞지 않는 까닭은 무엇인가요?','종이 크기를 같게 했으므로 크기 차이로 설명할 수 없어요.','같은 크기의 흰 종이 두 장',['같게 한 크기','주장과 기록 대조']),
      ('classification','같게 한 것 / 다르게 한 것으로 나누세요.',['종이 크기','거리','판 유무'],'같게: 종이 크기·거리 / 다르게: 판 유무','거리도 같게 했어요.'),
      ('관찰 기록을 두세 문장으로 정리하세요. 모든 판이라고 쓰지 마세요.','비교 방법과 이번에 관찰한 결과를 골라요.','같은 크기의 종이를 같은 거리에 놓고 판 유무를 달리했어요. 이번 기록에서는 판이 있는 가 종이가 더 어두워 보였어요.',['비교 조건 포함','이번 관찰의 범위 유지']),
      ('두 종이의 크기는 같았어요.','크기 때문이라는 말이 맞는지 크기 기록부터 볼게. 같았으니 그 차이로 설명하면 안 되겠어. 달리한 조건과 이번 결과를 붙여 읽어야 해.'),[('유무','있음과 없음'),('관찰','대상이나 변화를 자세히 살펴봄')],
      ('종이 다리','같은 길이의 종이 두 장을 사용했어요. 하나는 평평하게, 하나는 접어서 받쳤어요. 접은 종이가 블록을 더 많이 버텼다고 기록했어요.','다르게 한 조건과 이번 결과를 말하세요.','접었는지를 달리했고, 이 기록에서 접은 종이가 블록을 더 많이 버텼어요.','하나는 평평하게',['바꾼 조건','관찰 결과']),
      ('독서 자리 비교','같은 책을 같은 시간 동안 읽었어요. 첫날은 복도 쪽, 둘째 날은 창가 쪽에 앉았어요. 둘째 날에 소음이 적었다고 적었어요.','읽은 시간이 달라 소음이 적었다는 설명은 왜 맞지 않나요?','읽은 시간은 같았으므로 시간 차이로 설명할 수 없어요.','같은 시간 동안',['고정 조건','주장 대조']),
      ('같은 크기와 판을 세움에 서로 다른 표시를 해 보세요.','크기는 같고 판 유무는 달라요.'))

    add(2,'종이 동물 전시 약속','미술','분류 안내','COM-A6',[
      '우리 반은 종이 동물을 전시해요. 종이를 접어 만든 동물과 종이를 말아 만든 동물이 있어요. 만든 모양이 쉽게 바뀌지 않도록 전시 자리를 정하기로 했어요. 동물 이름만 보고 자리를 나누지는 않아요.',
      '납작하게 놓이는 작품은 낮은 판 위에 두어요. 세워야 하는 작품은 칸막이가 있는 받침에 두어요. 날개가 넓어 옆 작품과 닿는 작품은 넓은 자리로 옮겨요. 친구들은 작품이 놓이는 모양과 필요한 공간을 함께 살펴요.',
      '유나는 종이 새를 낮은 판에 두었어요. 새가 납작하게 놓이고 날개도 옆 작품과 닿지 않았기 때문이에요. 민호의 종이 토끼는 세워야 해서 받침에 두었어요. 같은 종이로 만들었어도 필요한 자리가 다를 수 있어요.'],
      ('전시 자리를 나누는 기준은 무엇인가요?','놓이는 모양과 필요한 공간',[('동물 이름의 길이','이름으로 자리를 나누지 않는다고 했어요.'),('작품을 만든 친구의 이름','만든 사람은 자리 분류의 기준이 아니에요.')],'놓이는 모양과 필요한 공간','전시 자리는 작품을 안정되게 놓을 조건에 따라 정해요.'),
      ('같은 새 모양 작품이라도 전시 자리가 달라질 수 있나요?','세워야 하거나 날개가 넓으면 다른 자리가 필요할 수 있어요.','날개가 넓어 옆 작품과 닿는 작품',['동물 이름과 기준 구별','형태나 공간 조건 적용']),
      ('classification','작품을 알맞은 자리에 나누세요.',['납작하고 옆에 닿지 않는 물고기','세워야 하는 고양이','날개가 옆 작품에 닿는 새'],'물고기: 낮은 판 / 고양이: 칸막이 받침 / 새: 넓은 자리','세워야 하는 작품은'),
      ('전시 약속을 처음 보는 친구에게 두 가지 기준을 알려 주세요.','모양과 공간을 나누어 메모해요.','납작한 작품은 낮은 판에, 세워야 하는 작품은 받침에 놓아요. 옆 작품에 닿으면 넓은 자리로 옮겨요.',['모양에 따른 자리','공간 조건 추가']),
      ('동물 이름만 보고 자리를 나누지는 않아요.','새냐 토끼냐가 기준은 아니구나. 어떻게 놓이는지 먼저 보고, 옆에 닿는지도 살펴야겠어.'),[('칸막이','자리를 나누는 막'),('기준','나누거나 판단할 때 살피는 조건')],
      ('도구 서랍','잘 굴러가는 도구는 칸이 있는 서랍에, 납작한 도구는 얕은 서랍에 넣어요. 길어서 서랍 밖으로 나오는 것은 긴 상자에 넣어요.','긴 자가 서랍 밖으로 나올 때 어디에 두나요? 까닭도 말하세요.','길이 때문에 긴 상자에 두어요.','긴 상자에 넣어요.',['예외 조건 적용']),
      ('기록을 묶어요','기록 카드에는 오늘 한 놀이, 놀이 규칙, 느낀 점이 따로 있어요. 안내판에는 놀이하는 방법만 모으려고 해요.','안내판에 어떤 카드를 고르고 어떤 카드를 빼야 하나요?','놀이 규칙은 고르고, 오늘 한 놀이 목록과 느낀 점은 빼요.','놀이하는 방법만',['분류 목적','관련 정보 선별']),
      ('새와 토끼라는 이름을 가리고 놓이는 모양만 읽어 보세요.','납작한 것과 세워야 하는 것을 먼저 나누어요.'))

    add(2,'마지막 칸의 자리','국어','창작 이야기','EXP-V2-2',[
      '작은 전시 기차에는 그림을 세울 칸이 네 개 있었어요. 소라는 첫째 칸에 자기 그림을 놓았어요. 둘째 칸에는 준호의 그림, 셋째 칸에는 나래의 그림이 섰어요. 마지막 칸은 비어 있었어요.',
      '소라는 새로 전학 온 다온이를 바라보았어요. 다온이는 그림을 들고 기차 옆에서 발만 움직였어요. “이건 어디에 놓으면 돼?” 하고 작게 물었지요. 소라는 자기 그림을 꺼내려다가 손을 멈췄어요.',
      '“마지막 칸에 같이 세워 보자.” 소라가 빈 칸을 톡 두드렸어요. 다온이가 그림을 세우자 네 칸이 모두 찼어요. 소라는 자기 그림을 그대로 두고도 친구의 자리를 만들 수 있다는 걸 알았어요. 다온이는 기차의 끝을 손으로 살며시 잡고 웃었어요.'],
      ('소라가 자기 그림을 꺼내지 않아도 된 까닭은 무엇인가요?','마지막 칸이 비어 있었기 때문에',[('다온이가 그림을 가져오지 않아서','다온이는 그림을 들고 있었어요.'),('칸이 세 개뿐이어서','전시 기차에는 네 칸이 있었어요.')],'마지막 칸은 비어 있었어요.','빈 칸을 이용하면 자기 그림을 빼지 않고도 친구 그림을 놓을 수 있어요.'),
      ('다온이가 처음에는 자리를 몰랐다고 볼 수 있는 말은 무엇인가요?','“이건 어디에 놓으면 돼?”라는 말이에요.','이건 어디에 놓으면 돼?',['인물의 말 인용','상태와 말 연결']),
      ('ordering','사건을 일어난 차례로 쓰세요.',['다온이가 마지막 칸에 그림을 세움','소라가 빈 칸을 알려 줌','다온이가 놓을 곳을 물음'],'3 → 2 → 1','마지막 칸에 같이 세워 보자.'),
      ('다온이의 입장에서 처음과 나중의 마음을 두세 문장으로 쓰세요.','처음 말과 마지막 행동에서 근거를 골라요.','처음에는 놓을 자리를 몰라 망설였어요. 소라가 빈 칸을 알려 주어서 안심하고 웃었어요.',['처음과 나중 구별','말이나 행동에 근거한 마음']),
      ('다온이는 그림을 들고 기차 옆에서 발만 움직였어요.','발만 움직인 행동만으로 마음을 단정하지 않을게. 어디에 놓느냐는 말도 함께 보면 자리를 몰라 망설였다고 설명할 수 있겠어.'),[('망설이다','바로 행동하지 못하고 생각하다')],
      ('문 앞의 실내화','아람이는 문 앞에서 실내화를 든 채 서 있었어요. “내 신발장은 어느 칸이야?” 하고 물었어요. 하린이가 이름표를 가리키자 아람이는 고개를 끄덕였어요.','아람이가 처음 서 있던 까닭을 말과 연결해 설명하세요.','자기 신발장 칸을 몰라서예요. 어느 칸인지 물었어요.','내 신발장은 어느 칸이야?',['상태 추론','발언 근거']),
      ('방송 준비 메모','방송 메모: 민서는 발표문을 움켜쥐고 “첫 문장을 잊으면 어떡하지?”라고 말함. 연습한 뒤에는 먼저 마이크를 잡음.','연습 전후의 달라진 행동을 근거로 마음 변화를 설명하세요.','전에는 잊을까 걱정했고, 연습 뒤에는 더 자신 있게 시작하려고 했다고 볼 수 있어요.','먼저 마이크를 잡음',['행동 변화','추론 범위']),
      ('소라가 그림을 뺄 필요가 있는지 네 칸을 그려 보세요.','세 칸에 그림이 있고 한 칸이 비어 있어요.'))

    add(2,'운동 놀이 설명서','체육','절차 글쓰기','EXP-W3',[
      '우리 반은 공을 굴려 색 고리에 넣는 놀이를 만들었어요. 공은 하나, 고리는 두 개를 준비해요. 출발선은 고리에서 세 걸음 떨어진 곳에 그어요. 세 걸음은 이번 놀이에서 정한 거리예요.',
      '첫 친구는 출발선 뒤에 서요. 앞에 사람이 없는지 보고 공을 천천히 굴려요. 공이 멈추면 도우미가 공을 가져와 다음 친구에게 줘요. 공이 움직일 때 함께 뛰어가지는 않아요.',
      '재이는 설명서에 “공을 가져온다. 공을 굴린다. 선을 그린다”라고 적었어요. 이대로 읽으면 준비와 놀이 순서가 뒤섞여요. 준비할 것, 놀이할 차례, 주의할 일을 나누어 쓰면 처음 하는 친구도 따라 하기 쉬워요.'],
      ('설명서의 맨 앞에 둘 내용은 무엇인가요?','공과 고리를 준비하고 선을 그리는 일',[('공이 멈춘 뒤 가져오는 일','놀이를 시작한 뒤의 일이에요.'),('다음 친구에게 공을 주는 일','한 친구가 굴린 뒤의 일이에요.')],'공은 하나, 고리는 두 개를 준비해요.','도구와 출발선을 먼저 준비해야 놀이를 시작할 수 있어요.'),
      ('공이 움직일 때 함께 뛰어가면 설명서의 어느 약속과 맞지 않나요?','공이 멈춘 뒤 도우미가 가져오는 약속과 맞지 않아요.','공이 멈추면 도우미가',['멈춘 뒤 행동','동시 행동과 순서 구별']),
      ('ordering','실제 놀이 순서대로 배열하세요.',['멈춘 공을 가져온다','출발선 뒤에 선다','앞을 확인하고 굴린다'],'2 → 3 → 1','첫 친구는 출발선 뒤에'),
      ('설명서를 준비 / 놀이 차례 / 주의로 나눠 세네 문장으로 쓰세요.','필요한 물건과 행동 순서, 주의 한 가지를 메모해요.','공 하나와 고리 두 개를 준비하고 선을 그어요. 선 뒤에 서서 앞을 살핀 다음 공을 굴려요. 멈추면 도우미가 가져와요. 공을 따라 뛰지 않아요.',['준비와 실행 구분','행동 순서','주의할 일']),
      ('준비와 놀이 순서가 뒤섞여요.','공을 가져오려면 먼저 굴려야 하네. 그런데 굴리려면 선과 도구가 필요해. 해야 할 일의 앞뒤를 거꾸로 살펴 순서를 고쳐볼게.'),[('출발선','놀이를 시작할 자리를 표시한 선')],
      ('씨앗 봉투 접기','정사각 종이와 풀을 준비해요. 종이를 반 접고 옆을 붙여요. 풀이 마른 뒤 씨앗을 넣어요.','준비와 실행을 나누어 안내 두 문장으로 쓰세요.','종이와 풀을 준비해요. 반 접어 옆을 붙이고 마르면 씨앗을 넣어요.','풀이 마른 뒤',['준비와 실행','마른 뒤 조건']),
      ('자료를 빌리는 법','대여 카드: ① 번호표 받기 ② 도구 고르기 ③ 이름 적기 ④ 도구 받기. 반납은 사용 후 별도 바구니에서 해요.','도구 받기 전 절차와 사용 후 절차를 나눠 설명하세요.','번호표를 받고 도구를 고른 뒤 이름을 적으면 받아요. 사용 후에는 바구니에 반납해요.','반납은 사용 후',['전후 구분','순서 유지']),
      ('준비하지 않으면 할 수 없는 행동을 찾아요.','공과 고리, 선을 준비해야 굴릴 수 있어요.'))
